// Gerado por scripts/build.mjs. Edite os módulos originais e execute npm run build.
(()=>{
// Conteúdo demonstrativo baseado nos nomes e serviços visíveis nos PNGs.
const clinics = ['Clínica PetCare','Clínica 02','Clínica 03','Clínica 04','Clínica 05'].map((name,i)=>({id:String(i+1),name}));
const services = ['Consulta','Retorno','Exame','Procedimento clínico'];
const initialMessages = [{sender:'clinic',text:'Olá, tudo bem?'}];

const KEY='petcare-demo-v1';
const defaults=()=>({profile:{name:'Pedro Alves Cabral'},appointments:[],messages:{},favorites:[]});
function readState(){try{return {...defaults(),...JSON.parse(localStorage.getItem(KEY)||'{}')};}catch{return defaults();}}
function writeState(value){try{localStorage.setItem(KEY,JSON.stringify(value));return true;}catch{return false;}}
function validAppointment(date,time,now=new Date()) {const value=new Date(`${date}T${time}:00`);return Number.isFinite(value.getTime()) && value>now;}
function overlaps(items,clinic,date,time){return items.some(a=>a.clinic===clinic&&a.date===date&&a.time===time);}
function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}

const esc = escapeHtml;

const icons={home:'⌂',chat:'▤',schedule:'▦',profile:'♟',menu:'⚙',notification:'♧',back:'‹',heart:'♡',search:'⌕'};
function button(text,route,cls=''){return `<a class="button ${cls}" href="#/${route}">${text}</a>`;}
function logo(){return '<img class="logo" src="assets/logo.png" alt="PetCare">';}
function field(label,name,type='text',value='',attrs=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;}
function nav(active){return `<nav class="bottom" aria-label="Navegação principal">${[['home','Início'],['chats','Conversas'],['schedule','Agenda'],['profile','Perfil']].map(([r,l])=>`<a href="#/${r}" class="${active===r?'active':''}" ${active===r?'aria-current="page"':''} aria-label="${l}"><span aria-hidden="true">${icons[r==='chats'?'chat':r]}</span><small>${l}</small></a>`).join('')}</nav>`;}
function header(title,back='home',extra=''){return `<header class="page-header"><a href="#/${back}" aria-label="Voltar">‹</a><h1>${title}</h1>${extra||'<span></span>'}</header>`;}
function shell(content,active){return `<div class="app-shell">${content}${nav(active)}</div>`;}
function clinicRow(c,route='clinic'){return `<a class="clinic-row" href="#/${route}/${c.id}"><img src="assets/clinic.png" alt=""><div><strong>${esc(c.name)}</strong></div><span aria-hidden="true">›</span></a>`;}
function auth(content){
 const images=content.match(/<img\b[^>]*>/g)||[];
 const panel=content.replace(/<img\b[^>]*>/g,'');
 return `<main class="auth"><div class="auth-visual">${images.join('')}</div><div class="auth-panel">${panel}</div></main>`;
}




const app=document.querySelector('#app');
let state=readState(), selectedDate='', month=new Date().getMonth(), year=new Date().getFullYear(), chosenService=services[0],profileTab='history';
const route=()=>location.hash.replace(/^#\/?/,'').split('/');
const go=r=>{location.hash='/'+r;};
function toast(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),5000);}
function save(){if(!writeState(state))toast('Não foi possível guardar os dados neste navegador.');}
const dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('pt-BR');
const dateISO=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
function appointmentCard(a){return `<article class="appointment"><div><strong>${esc(a.service)} · ${esc(clinics.find(c=>c.id===a.clinic)?.name||'Clínica')}</strong><small>${dateLabel(a.date)} às ${esc(a.time)}</small><small>${esc(a.pet)}</small></div><button class="icon-button" data-action="cancel" data-id="${esc(a.id)}" aria-label="Remover agendamento">×</button></article>`;}
function calendar(){const first=new Date(year,month,1).getDay(),days=new Date(year,month+1,0).getDate();return `<div class="calendar-header"><button data-action="prev-month" aria-label="Mês anterior">‹</button><strong>${new Date(year,month).toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</strong><button data-action="next-month" aria-label="Próximo mês">›</button></div><div class="calendar">${['D','S','T','Q','Q','S','S'].map(d=>`<span class="weekday">${d}</span>`).join('')}${'<span></span>'.repeat(first)}${Array.from({length:days},(_,i)=>{const d=dateISO(new Date(year,month,i+1));return `<button data-action="select-date" data-date="${d}" class="${d===selectedDate?'selected ':''}${state.appointments.some(a=>a.date===d)?'has-event':''}" aria-label="${dateLabel(d)}" aria-pressed="${d===selectedDate}">${i+1}</button>`;}).join('')}</div>`;}
const features=[['Agende horários com facilidade','Marque consultas de forma rápida e prática, direto pelo app — sem filas, sem complicação!'],['Tenha todo o histórico do seu pet','Acompanhe vacinas, exames e tratamentos em um só lugar, de forma organizada e segura.'],['Lembretes na hora certa','Receba alertas automáticos para não esquecer de consultas, vacinas ou medicações.']];
function render(){let [r='splash',id]=route();if(!r)r='splash';const c=clinics.find(c=>c.id===id)||clinics[0];let html='';
if(r==='splash')html=auth(`${logo()}${button('Começar','onboarding/1','white')}`);
else if(r==='onboarding'){const n=Math.min(3,Math.max(1,Number(id)||1));html=auth(`<a href="#/start" class="skip-onboarding">Pular</a>${logo()}<h1>${features[n-1][0]}</h1><img class="onboarding-image" src="assets/onboarding${n}.png" alt="Ilustração do recurso"><p class="description">${features[n-1][1]}</p><div class="dots" aria-label="Etapa ${n} de 3">${[1,2,3].map(i=>`<span class="dot ${n===i?'current':''}"></span>`).join('')}</div>${button(n===3?'Começar →':'Próximo →',n===3?'start':`onboarding/${n+1}`)}`);}
else if(r==='start')html=auth(`${logo()}<img class="start-pets" src="assets/pets.png" alt="Cão e gato"><div class="start-actions">${button('Criar conta!','register','white')}${button('Acessar','login')}</div>`);
else if(r==='login')html=auth(`${logo()}<form data-form="login"><h1>BEM VINDO!</h1>${field('Email','email','email','','required autocomplete="email"')}${field('Senha','password','password','','required autocomplete="off"')}<p><a class="text-link" href="#/forgot">Esqueceu sua senha?</a></p><button class="primary" type="submit">Entrar</button><p>Não possui uma conta? <a class="text-link" href="#/register">Cadastre-se!</a></p></form>`);
else if(r==='register')html=auth(`${logo()}<form data-form="register"><h1>Cadastro</h1>${field('Nome completo','name','text','','required maxlength="100" autocomplete="name"')}${field('Email','email','email','','required autocomplete="email"')}${field('Senha','password','password','','required minlength="6" autocomplete="off"')}${field('Confirme sua senha','confirm','password','','required minlength="6" autocomplete="off"')}<button class="primary" type="submit">Acessar</button><p>Já possui uma conta? <a class="text-link" href="#/login">Entre!</a></p></form>`);
else if(r==='confirm')html=auth(`<img class="envelope" src="assets/envelope.png" alt="Envelope"><div class="confirmation"><h1>Cadastro</h1><p>Confira seus dados antes de continuar.</p>${button('Continuar','home')}<p><button class="icon-button" data-action="backend">Reenviar</button></p></div>`);
else if(r==='forgot')html=auth(`<a class="back" href="#/login" aria-label="Voltar">‹</a><form data-form="forgot"><h1>Esqueci minha senha</h1><p>Informe o email cadastrado na sua conta para receber instruções.</p>${field('Email','email','email','','required')}<button type="submit" class="primary">Enviar</button></form>`);
else if(r==='recovery')html=auth(`<img class="envelope" src="assets/envelope.png" alt="Envelope"><div class="confirmation"><h1>Recuperar senha</h1><p>A recuperação de senha está indisponível no momento. Tente novamente mais tarde.</p>${button('Voltar para o login','login')}</div>`);
else if(r==='home')html=shell(`<header class="toolbar"><a href="#/menu" aria-label="Configurações">⚙</a><span class="location">Olá, ${esc(state.profile.name.split(' ')[0])}!</span><a href="#/notifications" aria-label="Notificações">♧</a></header><div class="search"><label>O que seu pet precisa?<input id="home-search" type="search" placeholder="Buscar clínica ou serviço"></label><div class="categories">${[['✚','Clínico geral'],['♧','Vacinação'],['✳','Emergência']].map(([i,t])=>`<a class="category" href="#/clinics"><span aria-hidden="true">${i}</span>${t}</a>`).join('')}</div></div><main class="content home-content"><section><div class="section-title"><h2>Clínicas</h2><a href="#/clinics">Ver todas</a></div><div class="cards">${clinics.slice(0,3).map(c=>`<a data-search="${esc(c.name.toLowerCase())}" class="card" href="#/clinic/${c.id}"><img src="assets/consultation.png" alt=""><strong>${esc(c.name)}</strong></a>`).join('')}</div><p id="no-results" hidden>Nenhuma clínica encontrada.</p></section><aside class="banner"><div><strong>Cuide de quem está sempre ao seu lado.</strong><p>Encontre atendimento para seu pet.</p>${button('Ver clínicas','clinics','white')}</div><img src="assets/consultation.png" alt="Atendimento veterinário"></aside><section><h2>Vitaminas</h2><div class="cards">${[1,2,3].map(i=>`<button class="card" data-action="catalog"><img src="assets/vaccine.png" alt=""><strong>Vitamina ${i}</strong><small>Ver informações</small></button>`).join('')}</div></section><section><h2>Medicamentos</h2><div class="cards">${[1,2,3].map(i=>`<button class="card" data-action="catalog"><img src="assets/consultation.png" alt=""><strong>Medicamento ${i}</strong><small>Ver informações</small></button>`).join('')}</div></section></main>`,'home');
else if(r==='clinics')html=shell(`${header('Clínicas')}<main class="content"><label>Buscar clínica<input id="clinic-search" type="search" placeholder="Nome da clínica"></label><div class="clinic-list">${clinics.map(c=>`<div data-search="${esc(c.name.toLowerCase())}">${clinicRow(c)}</div>`).join('')}<p id="no-results" hidden>Nenhuma clínica encontrada.</p></div></main>`,'home');
else if(r==='clinic')html=shell(`${header('Serviços da clínica','clinics',`<div class="tools"><button class="icon-button" data-action="favorite" data-id="${c.id}" aria-label="${state.favorites.includes(c.id)?'Remover dos favoritos':'Adicionar aos favoritos'}">${state.favorites.includes(c.id)?'♥':'♡'}</button><button class="icon-button" data-action="help" aria-label="Ajuda">?</button></div>`)}<main class="content">${clinicRow(c)}<form data-form="select-service" data-clinic="${c.id}">${services.map((s,i)=>`<label class="service"><img src="assets/${i===0?'consultation':'vaccine'}.png" alt=""><span>${s}</span><input type="radio" name="service" value="${esc(s)}" ${s===chosenService?'checked':''} required></label>`).join('')}<button class="primary" type="submit">Acessar</button></form></main><dialog class="help-dialog"><h2>Agendamento</h2><p>Selecione um serviço e, na próxima tela, informe o pet, a data e o horário.</p><button class="primary button" data-action="close-help">OK</button></dialog>`,'home');
else if(r==='booking')html=shell(`${header('Agendar atendimento',`clinic/${c.id}`)}<main class="content"><h2>${esc(c.name)}</h2><form class="edit-form" data-form="booking" data-clinic="${c.id}"><label>Serviço<select name="service">${services.map(s=>`<option ${s===chosenService?'selected':''}>${s}</option>`).join('')}</select></label>${field('Nome do pet','pet','text','','required maxlength="80"')}${field('Data','date','date',selectedDate,`required min="${dateISO(new Date())}"`)}${field('Horário','time','time','','required')}<button type="submit" class="primary">Cadastrar agendamento</button></form></main>`,'schedule');
else if(r==='schedule'){const items=state.appointments.filter(a=>!selectedDate||a.date===selectedDate).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));html=shell(`<header class="toolbar"><strong>Olá, ${esc(state.profile.name.split(' ')[0])}!</strong></header><main class="content"><div class="schedule-title"><h1>Minha agenda</h1><a href="#/clinics" aria-label="Novo agendamento">+</a></div>${calendar()}<div class="section-title"><h2>${selectedDate?dateLabel(selectedDate):'Meus agendamentos'}</h2>${selectedDate?'<button data-action="clear-date">Mostrar todos</button>':''}</div>${items.length?items.map(appointmentCard).join(''):'<p class="empty">Nenhum agendamento neste período.</p>'}</main>`,'schedule');}
else if(r==='profile')html=shell(`${header('Perfil')}<main class="content profile"><img class="avatar" src="assets/avatar.png" alt="Foto de perfil">${button('Editar perfil','edit-profile')}<div class="profile-name">${esc(state.profile.name)}</div><div class="tabs"><button data-action="profile-history" class="${profileTab==='history'?'active':''}">Histórico</button><button data-action="profile-pets" class="${profileTab==='pets'?'active':''}">Meus pets</button></div>${profileTab==='history'?`<h2>Minhas consultas</h2>${state.appointments.length?state.appointments.map(appointmentCard).join(''):'<p class="empty">Sem consultas cadastradas.</p>'}`:'<p class="empty">Nenhum pet cadastrado.</p>'}</main>`,'profile');
else if(r==='edit-profile')html=shell(`${header('Editar perfil','profile')}<main class="content"><form class="edit-form" data-form="profile">${field('Nome completo','name','text',state.profile.name,'required maxlength="100"')}<button class="primary" type="submit">Salvar</button></form></main>`,'profile');
else if(r==='menu')html=shell(`${header('Configurações')}<main class="content"><div class="menu-list">${[['Notificações','notifications'],['Configurações','settings'],['Favoritos','favorites'],['Pagamentos','payments'],['Endereços','addresses'],['Ajuda','help'],['Logout','logout']].map(([t,r])=>`<a href="#/${r}">${t}<span>›</span></a>`).join('')}</div></main>`,'profile');
else if(r==='favorites')html=shell(`${header('Favoritos','menu')}<main class="content">${clinics.filter(c=>state.favorites.includes(c.id)).map(c=>clinicRow(c)).join('')||'<p class="empty">Nenhuma clínica favorita.</p>'}</main>`,'profile');
else if(r==='notifications')html=shell(`${header('Notificações','menu')}<main>${state.appointments.length?state.appointments.map(a=>`<article class="notification"><span aria-hidden="true">♧</span><p>${esc(a.service)} de ${esc(a.pet)}<br><small>${dateLabel(a.date)} · ${esc(a.time)}</small></p></article>`).join(''):'<p class="empty">Nenhuma notificação.</p>'}</main>`,'home');
else if(r==='chats')html=shell(`${header('Conversas')}<main class="content clinic-list">${clinics.map(c=>clinicRow(c,'chat')).join('')}</main>`,'chats');
else if(r==='chat'){const messages=state.messages[c.id]||initialMessages;html=shell(`${header(c.name,'chats')}<main class="messages">${messages.map(m=>`<div class="bubble ${m.sender==='me'?'me':''}">${esc(m.text)}</div>`).join('')}</main><form class="chat-form" data-form="message" data-clinic="${c.id}"><label class="sr-only" hidden for="message">Mensagem</label><input id="message" name="message" aria-label="Mensagem" placeholder="Mensagem" required maxlength="1000"><button type="submit" aria-label="Adicionar mensagem">›</button></form>`,'chats');}
else if(r==='logout'){go('login');return;}
else if(['settings','payments','addresses','help'].includes(r)){const titles={settings:'Configurações',payments:'Pagamentos',addresses:'Endereços',help:'Ajuda'};html=shell(`${header(titles[r],'menu')}<main class="content"><p>${r==='help'?'Use o menu para navegar. Em Clínicas, selecione um serviço, informe o pet e escolha a data e o horário para adicionar um agendamento à sua agenda.':'Nenhuma informação disponível no momento.'}</p></main>`,'profile');}
else html=shell(`${header('Página não encontrada')}<main class="content">${button('Voltar ao início','home')}</main>`,'home');
app.innerHTML=html;if(r==='onboarding')app.querySelector('.auth').classList.add('onboarding');document.title=`PetCare · ${r}`;window.scrollTo(0,0);app.focus({preventScroll:true});}
app.addEventListener('submit',e=>{e.preventDefault();const form=e.target;if(!form.reportValidity())return;const d=Object.fromEntries(new FormData(form));switch(form.dataset.form){
case 'login':go('home');break;
case 'register':if(d.password!==d.confirm){toast('As senhas não coincidem.');return;}if(!d.name.trim()){toast('Informe seu nome.');return;}state.profile.name=d.name.trim();save();go('confirm');break;
case 'forgot':go('recovery');break;
case 'profile':if(!d.name.trim()){toast('Informe seu nome.');return;}state.profile.name=d.name.trim();save();go('profile');toast('Nome atualizado.');break;
case 'select-service':chosenService=d.service;go('booking/'+form.dataset.clinic);break;
case 'booking':if(!d.pet.trim()){toast('Informe o nome do pet.');return;}if(!validAppointment(d.date,d.time)){toast('Escolha uma data e um horário futuros.');return;}if(overlaps(state.appointments,form.dataset.clinic,d.date,d.time)){toast('Já existe um agendamento para esta clínica nesse horário.');return;}state.appointments.push({id:crypto.randomUUID(),clinic:form.dataset.clinic,service:d.service,pet:d.pet.trim(),date:d.date,time:d.time});save();selectedDate='';go('schedule');toast('Agendamento adicionado à agenda.');break;
case 'message':if(!d.message.trim())return;const cid=form.dataset.clinic;state.messages[cid]??=initialMessages.map(m=>({...m}));state.messages[cid].push({sender:'me',text:d.message.trim()});save();render();app.querySelector('#message')?.focus();break;
}});
app.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;switch(b.dataset.action){case 'backend':toast('Este serviço está indisponível no momento.');break;case 'catalog':toast('Informações indisponíveis no momento.');break;case 'help':app.querySelector('dialog').showModal();break;case 'close-help':app.querySelector('dialog').close();break;case 'favorite':state.favorites=state.favorites.includes(b.dataset.id)?state.favorites.filter(id=>id!==b.dataset.id):[...state.favorites,b.dataset.id];save();render();break;case 'cancel':state.appointments=state.appointments.filter(a=>a.id!==b.dataset.id);save();render();toast('Agendamento removido.');break;case 'prev-month':month--;if(month<0){month=11;year--;}render();break;case 'next-month':month++;if(month>11){month=0;year++;}render();break;case 'select-date':selectedDate=b.dataset.date;render();break;case 'clear-date':selectedDate='';render();break;case 'profile-history':profileTab='history';render();break;case 'profile-pets':profileTab='pets';render();break;}});
app.addEventListener('input',e=>{if(!['home-search','clinic-search'].includes(e.target.id))return;const q=e.target.value.toLocaleLowerCase('pt-BR').trim();let count=0;app.querySelectorAll('[data-search]').forEach(el=>{el.hidden=!el.dataset.search.includes(q);if(!el.hidden)count++;});app.querySelector('#no-results').hidden=count>0;});
window.addEventListener('hashchange',render);render();

})();
